const CONNECTION_BY_ID = new Map(Object.values(ORGAN_CONNECTIONS).flat().map(c => [c.id,c]));
export const getOrganConnection = (id:string|null|undefined):OrganConnection|null => id ? CONNECTION_BY_ID.get(id) || null : null;
export const getNodeConnection = (owner:string,nodeId:string):OrganConnection|undefined => ORGAN_CONNECTIONS[owner]?.find(c=>c.nodeId===nodeId);
